// Request 构造带默认头部的请求（供需要自定义头的调用方使用）。
func (f *Fetcher) Request(ctx context.Context, rawURL string) (*http.Request, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, rawURL, nil)
	if err != nil {
