func StripHTMLTags(s string) string {
	return strings.TrimSpace(tagRe.ReplaceAllString(s, ""))
}

// CleanPath 是 path.Clean 的导出包装（供外部使用）。
func CleanPath(p string) string { return path.Clean(p) }

