			Published: parseTime(it.PubDate),
			Summary:   htmlToText(desc),
		})
	}
	if len(items) == 0 {
		return nil, fmt.Errorf("RSS 无条目")
	}
	return items, nil
}

func parseAtom(data []byte) ([]Item, error) {
